var fs = require('fs');
var path = require('path');
var temp = require('temp');
var test = require('tap').test;
var rimraf = require('rimraf');
var browserify = require('browserify');
var requirify = require('../');
var treenherit = require('../../../packages/mendel-treenherit');
var requireTransform = require('../../../packages/mendel-development/require-transform');

var srcDir = path.resolve(__dirname, '../../../test/app-samples/1');

temp.track();
var buildDir = temp.mkdirSync('build-requirify');

var entry = 'app/number-list.js';
var variationDirs = ['test_A', 'app'];

var mendelRequireRegexp = /__mendel_require__\(/;
var requireRegexp = /\brequire\(/;

function run(t, outDir, outFile, cb) {
    t.plan(4);
    var b = browserify({
        basedir: srcDir,
        entries: [path.join(srcDir, entry)],
    });
    b.transform(treenherit, {
        dirs: variationDirs,
    });
    b.plugin(requirify, {
        outdir: outDir,
        dirs: variationDirs,
    });
    b.bundle(function (err) {
        if (err) {
            t.fail(err.message || err);
        }

        // wait for file to be written
        setTimeout(function () {
            var src;
            try {
                src = fs.readFileSync(outFile, 'utf-8');
            } catch (e) {
                t.fail('Failed to open dest file: ' + outFile);
            }

            t.match(src, mendelRequireRegexp);
            t.notMatch(src, requireRegexp);

            var wrapper = requireTransform.wrapper;
            t.equal(src.indexOf(wrapper[0]), 0, 'wrapper prelude pos');
            t.equal(
                src.indexOf(wrapper[1]),
                src.length - wrapper[1].length,
                'wrapper epilogue pos'
            );

            temp.cleanup(function () {
                if (cb) {
                    return cb(t);
                }
                t.end();
            });
        }, 150);
    });
}

test('mendel-requirify', function (t) {
    var outFile = path.join(buildDir, entry);

    run(t, buildDir, outFile);
});

test('mendel-requirify-defaults', function (t) {
    var outDir = path.join(process.cwd(), 'build-requirify');
    var outFile = path.join(outDir, entry);

    run(t, null, outFile, function (t) {
        rimraf(outDir, function () {
            t.end();
        });
    });
});

const tap = require('tap');
const fs = require('fs');
const os = require('os');
const path = require('path');
const rimraf = require('rimraf');
const browserify = require('browserify');
const requirify = require('../');

const fixtures = path.join(__dirname, 'fixtures');
const entry = path.join(fixtures, 'entry.js');
// entry-skip.js requires no variation-matched module, so bundling it never
// exercises the write path — needed to test the skip branches in isolation.
const entrySkip = path.join(fixtures, 'entry-skip.js');
const dirs = ['variantA'];

let counter = 0;
function tmpOutdir() {
    counter += 1;
    return path.join(
        os.tmpdir(),
        'mendel-requirify-test-' + process.pid + '-' + counter
    );
}

// out.end(...) in index.js has no completion callback, so the write can
// still be in flight when the bundle stream ends; settle before asserting.
function bundle(b) {
    return new Promise((resolve, reject) => {
        const s = b.bundle();
        s.on('error', reject);
        s.resume();
        s.on('end', () => setTimeout(resolve, 200));
    });
}

tap.test(
    'writes a transformed copy of each variation-matched module',
    async (t) => {
        const outdir = tmpOutdir();
        const b = browserify([entry]);
        requirify(b, { outdir, dirs });

        await bundle(b);

        const mainPath = path.join(outdir, 'variantA', 'main.js');
        const helperPath = path.join(outdir, 'variantA', 'helper.js');
        t.ok(fs.existsSync(mainPath), 'writes variantA/main.js');
        t.ok(fs.existsSync(helperPath), 'writes variantA/helper.js');

        const rawSource = fs.readFileSync(
            path.join(fixtures, 'variantA', 'helper.js'),
            'utf8'
        );
        const writtenSource = fs.readFileSync(helperPath, 'utf8');

        t.not(
            writtenSource,
            rawSource,
            'written source differs from the raw fixture source'
        );
        t.match(
            writtenSource,
            /__mendel_module__/,
            'written source carries the mendel require-transform wrapper'
        );

        rimraf.sync(outdir);
        t.end();
    }
);

tap.test('creates missing output directories', async (t) => {
    const outdir = path.join(tmpOutdir(), 'a', 'b', 'c', 'd');
    t.notOk(fs.existsSync(outdir), 'outdir does not exist yet');

    const b = browserify([entry]);
    requirify(b, { outdir, dirs });

    await bundle(b);

    const mainPath = path.join(outdir, 'variantA', 'main.js');
    t.ok(
        fs.existsSync(mainPath),
        'writes into the deeply nested outdir it created'
    );

    rimraf.sync(outdir);
    t.end();
});

tap.test('skips modules under node_modules', async (t) => {
    const outdir = tmpOutdir();
    const b = browserify([entrySkip]);
    requirify(b, { outdir, dirs });

    await bundle(b);

    // node_modules/variantA resolves under the same "variantA" chain name;
    // if the node_modules skip were broken, it would land here instead.
    const nodeModulesOutput = path.join(outdir, 'variantA', 'index.js');
    t.notOk(
        fs.existsSync(nodeModulesOutput),
        'does not write a file for the node_modules package'
    );

    rimraf.sync(outdir);
    t.end();
});

tap.test('skips modules outside the variation chain', async (t) => {
    const outdir = tmpOutdir();
    const b = browserify([entrySkip]);
    requirify(b, { outdir, dirs });

    await bundle(b);

    t.notOk(
        fs.existsSync(path.join(outdir, 'base')),
        'does not write base-tree modules that have no variation match'
    );

    rimraf.sync(outdir);
    t.end();
});

tap.test('re-registers its hooks when browserify resets', async (t) => {
    const outdir = tmpOutdir();
    const b = browserify([entry]);
    requirify(b, { outdir, dirs });

    await bundle(b);
    rimraf.sync(outdir);
    t.notOk(fs.existsSync(outdir), 'cleared output between bundle runs');

    await bundle(b);

    const mainPath = path.join(outdir, 'variantA', 'main.js');
    t.ok(
        fs.existsSync(mainPath),
        'still writes output on the second bundle from the same instance'
    );

    rimraf.sync(outdir);
    t.end();
});

const path = require('path');
const { test } = require('tap');
const rimraf = require('rimraf');
const fs = require('fs');
const Pipeline = require('../../mendel-pipeline');
const appPath = path.join(__dirname, './css-samples');
const buildPath = path.join(appPath, 'build');

rimraf.sync(buildPath);
rimraf.sync(path.join(appPath, '.mendelipc'));

test('mendel-outlet-css sanity test', function (t) {
    t.plan(4);

    process.chdir(appPath);
    process.env.MENDELRC = '.mendelrc';

    const mendel = new Pipeline();
    mendel.run(function (error) {
        try {
            if (error) {
                console.error(error);
                return t.bailout('should create manifest but failed');
            }

            const css = fs.readFileSync(
                path.join(buildPath, 'main.css'),
                'utf8'
            );

            t.notMatch(css, /background: red/);
            t.match(css, /padding: 0/);
            t.match(css, /background: blue/);
            // From LESS
            t.match(css, /background: #1111ff/);
        } finally {
            // Daemon leaves IPC handles open; same as CLI after build.
            if (typeof mendel.onForceExit === 'function') {
                try {
                    mendel.onForceExit();
                } catch (e) {
                    /* ignore */
                }
            }
            setImmediate(() => process.exit(t.passing() ? 0 : 1));
        }
    });
});

const path = require('path');
const fs = require('fs');
const rimraf = require('rimraf');

const monorepoPackages = path.resolve(__dirname, '../../..');
const outletManifest = path.join(monorepoPackages, 'mendel-outlet-manifest');
const parserPlaintext = path.join(monorepoPackages, 'mendel-parser-plaintext');
const mendelPipeline = path.resolve(__dirname, '../..');

exports.parserPlaintext = parserPlaintext;

/**
 * Stage a read-only fixture into a disposable, gitignored run directory.
 *
 * The fixture is the single source of truth and is never written to; the run
 * directory holds everything a build generates (.mendelrc, .mendelipc, build/)
 * as real files next to links back to the fixture's sources.
 *
 * Each top-level child of the fixture is linked individually rather than the
 * fixture root, because node and mendel find node_modules by walking up from
 * the requiring file to the project root: linking only ./app would make that
 * walk land in the run directory, which has no node_modules of its own.
 *
 * A fixture's dependencies live in `stubs/` and are staged as `node_modules/`,
 * because a directory actually named node_modules cannot be committed.
 *
 * Pass `copy: true` for tests that mutate their sources (watch-mode recovery,
 * error handling) so the mutation lands in the run directory instead of the
 * repository.
 */
exports.stageFixture = function stageFixture(
    fixtureDir,
    runName,
    { copy = false, runRoot } = {}
) {
    if (!fs.existsSync(fixtureDir)) {
        throw new Error(`stageFixture: no fixture at ${fixtureDir}`);
    }

    const runDir = path.join(
        runRoot || path.resolve(__dirname, '..'),
        '.mendel-runs',
        runName
    );
    rimraf.sync(runDir);
    fs.mkdirSync(runDir, { recursive: true });

    const place = (target, linkPath) => {
        if (copy) return fs.cpSync(target, linkPath, { recursive: true });
        try {
            fs.symlinkSync(
                path.relative(path.dirname(linkPath), target),
                linkPath
            );
        } catch (e) {
            // Windows refuses symlinks without privileges; a copy is
            // equivalent for a read-only fixture.
            if (e.code !== 'EPERM' && e.code !== 'EACCES') throw e;
            fs.cpSync(target, linkPath, { recursive: true });
        }
    };

    fs.readdirSync(fixtureDir)
        .filter((entry) => entry !== 'README.md' && entry !== 'expect')
        .forEach((entry) => {
            const target = path.join(fixtureDir, entry);
            if (entry === 'stubs') {
                const nodeModules = path.join(runDir, 'node_modules');
                fs.mkdirSync(nodeModules, { recursive: true });
                fs.readdirSync(target).forEach((pkg) =>
                    place(path.join(target, pkg), path.join(nodeModules, pkg))
                );
                return;
            }
            place(target, path.join(runDir, entry));
        });

    fs.mkdirSync(path.join(runDir, 'build'), { recursive: true });
    return runDir;
};

exports.buildPathFor = function buildPathFor(appPath) {
    return path.join(appPath, 'build');
};

exports.baseYaml = function baseYaml({
    types = '',
    transforms = '',
    entry,
    extraTop = '',
    bundleExtra = '',
}) {
    return `base-config:
  id: base
  dir: ./app
  outdir: ./build

variation-config:
  variation-dirs: []
  variations: {}
${extraTop}
transforms:${transforms ? '\n' + transforms : ' {}'}

types:
  js:
    extensions:
      - .js
${types}

outlets:
  - id: manifest
    plugin: ${outletManifest}
    options:
      uglify: false
      envify: false

bundles:
  main:
    outlet: manifest
    manifest: main.manifest.json
${bundleExtra ? bundleExtra + '\n' : ''}    entries:
      - ./${entry}
`;
};

exports.runBuild = function runBuild(appPath, yaml, callback) {
    fs.writeFileSync(path.join(appPath, '.mendelrc'), yaml);

    const prevCwd = process.cwd();
    process.chdir(appPath);
    delete process.env.MENDELRC;
    delete process.env.NODE_ENV;
    delete process.env.MENDEL_ENV;

    delete require.cache[require.resolve(mendelPipeline)];
    const MendelV2 = require(mendelPipeline);
    const mendel = new MendelV2();

    mendel.run((error) => {
        process.chdir(prevCwd);
        if (typeof mendel.onForceExit === 'function') {
            try {
                mendel.onForceExit();
            } catch (e) {
                /* ignore */
            }
        }
        callback(error);
    });
};

