const cssFixtures = globSync(__dirname + '/fixtures/css/**/*.css');

const cssResolver = new Resolver({
    cwd: __dirname,
    runtimes: ['browser', 'main'],
});

cssFixtures
    .filter((file) => file.endsWith('index.css'))
    .forEach((file) => {
        const dirname = path.dirname(file);
        cssResolver.setBaseDir(dirname);

        test(dirname, function (t) {
            return deps({
                file,
                source: readFileSync(file, 'utf8'),
                resolver: cssResolver,
            }).then((deps) => {
                t.equal(
                    Object.keys(deps).length,
                    3,
                    'malformed import is skipped without dropping the other dependencies'
                );

                t.equal(
                    deps["url('./foo.css')"],
                    false,
                    'url is not traversed or imported, it is treated as an external/lazy dependency'
                );

                const barDep = deps['./bar.css'];
                t.match(barDep.browser, /bar\.css$/);
                t.match(barDep.main, /bar\.css$/);

                const bazDep = deps['./baz.css'];
                t.match(
                    bazDep.browser,
                    /baz\.css$/,
                    'media query suffix is stripped from the import target'
                );
                t.match(bazDep.main, /baz\.css$/);
            });
        });
    });

const Mocha = require('mocha');
const MendelClient = require('mendel-pipeline/client');
const { execWithRegistry, exec } = require('mendel-exec');
const fs = require('fs');
const { globSync } = require('glob');
const errorMapper = require('mendel-exec/source-mapper');

const DEFAULT_OPTIONS = {
    watch: false,
    bail: false,
};

const client = new MendelClient({
    environment: 'test',
    noout: true,
}).run();

function MendelRunner(filePaths, options = {}) {
    const watch = options.watch || false;
    // Watch is a feature of mendel, not mocha.
    options = Object.assign({}, DEFAULT_OPTIONS, options, { watch: false });

    if (options.prelude) {
        options.prelude = globSync(options.prelude);
    }

    client.on('ready', function () {
        // Populate the global sandbox
        const sandbox = {};
        // Expose to mocha options for others.
        options.context = sandbox;

        // Istanbul support: it writes to global so make instrumentation
        // running in different context share object with the global one.
        sandbox.__coverage__ = global.__coverage__ = {};

        const mocha = new Mocha(options);

        const entries = client.registry.getEntriesByGlob(filePaths);
        entries.forEach((entry) => {
            // Pre-require populates mocha globals like before, beforeEach, and
            // etc...
            mocha.suite.emit('pre-require', sandbox, entry.id, mocha);

            options.prelude.forEach((file) => {
                const entry = client.registry.getEntry('./' + file);
                const id = entry ? entry.id : file;
                const source = entry
                    ? entry.source
                    : fs.readFileSync(file, 'utf8');

                exec(id, source, {
                    sandbox,
                    resolver(from, dep) {
                        const fromEntry = client.registry.getEntry(from);
                        if (!fromEntry) return null;
                        const depNorm = fromEntry.deps[dep]
                            ? fromEntry.deps[dep].main
                            : null;
                        if (!depNorm || depNorm.indexOf('/') < 0) return null;
                        const entries =
                            client.registry.getExecutableEntries(depNorm);
                        if (!entries) return null;
                        return entries.values().next().value;
                    },
                });
            });

            const variationConf = client.config.variationConfig.variations.find(
                ({ chain }) => chain[0] === entry.variation
            );
            const module = execWithRegistry(
                client.registry,
                entry.normalizedId,
                [variationConf],
                sandbox
            );
            mocha.suite.emit('require', module, entry.id, mocha);
        });

        const runner = mocha.run();
        runner.on('fail', (test, error) => {
            error.stack = errorMapper(error.stack, client.registry);
        });

        if (!watch) {
            runner.on('end', () => process.exit(runner.failures));
        }
    });

    client.on('change', function () {
        console.log('Mendel detected file change. Waiting for bundle...');
    });
}

module.exports = MendelRunner;

